import { Component, OnInit } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { PaymentService } from '../../../core/services/payment.service';
import { AuthService } from '../../../core/services/auth.service';
import { PaymentRecord } from '../../../core/models/payment.model';
import { User, Subscription } from '../../../core/models/user.model';

@Component({
  selector: 'app-payment-success',
  templateUrl: './payment-success.component.html',
  styleUrls: ['./payment-success.component.css']
})
export class PaymentSuccessComponent implements OnInit {
  paymentId: string | null = null;
  reference: string | null = null;
  paymentDetails: PaymentRecord | null = null;
  currentUser: User | null = null;
  userCredits: number | null = null;
  isSubscribed: boolean = false;
  isLoading = false;

  constructor(
    private route: ActivatedRoute,
    private paymentService: PaymentService,
    private authService: AuthService
  ) {}

  ngOnInit(): void {
    // Refresh user profile so updated credits/subscription are immediately synced
    this.refreshUserProfile();

    this.route.queryParams.subscribe(params => {
      this.paymentId = params['paymentId'] || params['id'] || null;
      this.reference = params['reference'] || params['merchant_order_id'] || null;

      if (this.paymentId) {
        this.fetchPaymentRecord(this.paymentId);
      }
    });
  }

  refreshUserProfile(): void {
    this.authService.getProfile().subscribe({
      next: (res) => {
        if (res && res.user) {
          this.currentUser = res.user;
          this.userCredits = typeof res.user.jobCredits === 'number' ? res.user.jobCredits : 0;
          this.isSubscribed = Boolean(
            res.user.subscription?.isActive &&
            res.user.subscription?.expiresAt &&
            new Date(res.user.subscription.expiresAt).getTime() > Date.now()
          );
        }
      }
    });
  }

  fetchPaymentRecord(id: string): void {
    this.isLoading = true;
    this.paymentService.getPaymentById(id).subscribe({
      next: (res) => {
        this.paymentDetails = res.data;
        this.isLoading = false;
        // Re-refresh profile once payment record confirms success
        this.refreshUserProfile();
      },
      error: () => {
        this.isLoading = false;
      }
    });
  }
}
<div class="payment-status-page container-narrow section-padding">
  <div class="card payment-status-card text-center p-5">
    <div class="status-icon-circle bg-success-light text-success mb-3">
      <i class="fa-solid fa-circle-check"></i>
    </div>

    <h1 class="status-title">Payment Successful!</h1>
    <p class="status-subtitle">
      Thank you for your purchase. Your payment has been processed securely via Paymob and your employer credits are now active.
    </p>

    <!-- Details Box if available -->
    <div class="payment-info-box text-left my-4" *ngIf="paymentDetails || reference">
      <div class="info-row" *ngIf="reference || paymentDetails?.specialReference">
        <span class="info-label">Transaction Reference:</span>
        <span class="info-val font-mono">{{ paymentDetails?.specialReference || reference }}</span>
      </div>
      <div class="info-row" *ngIf="paymentDetails">
        <span class="info-label">Amount Paid:</span>
        <span class="info-val font-bold">{{ paymentDetails.amount }} {{ paymentDetails.currency | uppercase }}</span>
      </div>
      <div class="info-row" *ngIf="paymentDetails">
        <span class="info-label">Payment Status:</span>
        <span class="badge badge-success">{{ paymentDetails.status }}</span>
      </div>
    </div>

    <div class="action-buttons-row mt-4">
      <a routerLink="/jobs/create" class="btn btn-primary btn-lg">
        <i class="fa-solid fa-plus"></i> Post a Job Opening Now
      </a>
      <a routerLink="/jobs/manage" class="btn btn-secondary btn-lg">
        View My Jobs
      </a>
    </div>
  </div>
</div>
